import { NEW_PLAYER_KEYWORD_SCENARIOS } from "./newPlayerKeywordScenarios.js";

export interface NewPlayerTopic { id: string; title: string; summary: string; paragraphs: string[]; takeaways: string[]; rules?: Array<{ title: string; points: string[] }>; examples?: Array<{ title: string; text: string; cards?: { id: string; name: string; caption?: string; landscape?: boolean }[] }> }
export interface NewPlayerDomain { id: string; name: string; color: string; identity: string; description: string }
export interface NewPlayerKeyword { term: string; explanation: string; example: string }
/** Short table-side definitions. Opening these never changes a lesson. */
export const NEW_PLAYER_TABLE_TERMS = [
  { term: "Draw", aliases: ["draw", "drawing"], explanation: "Take the top card of your main deck into your hand. It is an option you may use later; drawing does not play it.", example: "Draw a unit, then check whether you can pay for it." },
  { term: "Play", aliases: ["play", "playing"], explanation: "Use a card from your hand or another permitted place. Pay its cost first. A unit normally enters exhausted; a spell waits on the chain before its effect happens.", example: "Playing a unit is different from moving a unit already on the table." },
  { term: "Move", aliases: ["move", "moving"], explanation: "Change where a unit already on the table is. A normal move turns a ready unit sideways and usually goes between base and a battlefield during your Main phase.", example: "You do not pay its printed play cost again to move it." },
  { term: "Recall", aliases: ["recall", "recalls", "recalled"], explanation: "Return a unit or gear to its controller’s base. A recall is not a move and does not return the card to hand. It does not ready the card or remove damage unless the effect says so.", example: "An exhausted unit recalled from a battlefield stays exhausted in base." },
  { term: "Pay", aliases: ["pay", "paying", "cost", "costs"], explanation: "Spend the resources a card or ability asks for. A number means energy; domain symbols mean power. If both appear, pay both.", example: "A cost of 3 energy and 1 Mind power needs both amounts." },
  { term: "Energy", aliases: ["energy", "tap", "tapping"], explanation: "Pays numeric costs. Turn a ready basic rune sideways to make 1 energy. Available energy is spent when you pay a cost.", example: "Exhaust two ready basic runes for 1 energy each. You can now pay Watchful Sentry’s 2 energy." },
  { term: "Power", aliases: ["power", "recycle", "recycling"], explanation: "Pays domain symbols. A rune’s recycle ability returns it to the bottom of its deck and makes matching power. A sideways rune can still do this.", example: "Exhaust a Mind rune for energy, then recycle that same rune for Mind power." },
  { term: "Ready / exhausted", aliases: ["ready", "readies", "exhausted", "exhaust", "sideways", "upright"], explanation: "Ready means upright. Exhausted means sideways. Some actions turn a ready card sideways as their cost; it readies again when a rule or effect says so. Exhausted units can still defend and deal combat damage.", example: "A newly played unit normally waits until your next Awaken before making a normal move, but can defend its battlefield straight away." },
  { term: "Might", aliases: ["might", "damage", "combat"], explanation: "A unit’s current fighting strength. It supplies that much combat damage and dies if its marked damage reaches its current Might. Both sides deal combat damage together.", example: "A 3-Might unit and a 2-Might unit deal 3 and 2 damage at the same time." },
  { term: "Damage / heal", aliases: ["damage", "heal", "healed", "healing"], explanation: "Damage is marked separately from Might. Taking damage does not make a unit deal less combat damage. Healing removes marked damage; it does not increase Might or return a dead unit.", example: "A 4-Might unit with 2 damage still deals 4 combat damage. Healing it removes the 2 damage, leaving 4 Might." },
  { term: "Chain / resolve", aliases: ["chain", "resolve", "resolves", "resolving"], explanation: "The chain holds spells and abilities waiting to happen. Resolve means carry out the newest waiting item after the required passes. Older items wait for their own response window.", example: "Announcing a spell does not make its effect happen immediately." },
  { term: "Pass", aliases: ["pass", "passing", "passes"], explanation: "Choose not to add a play right now and give the other player their opportunity. Passing does not end your turn.", example: "After both players pass, a waiting effect can resolve or an empty showdown can finish." },
  { term: "Priority / focus", aliases: ["priority", "focus", "showdown"], explanation: "Priority is your chance to act or pass. In a showdown, focus determines who may start the next play while the chain is empty. You still need the right timing and cost.", example: "A Reaction can answer a waiting spell when you have priority." },
  { term: "Target", aliases: ["target", "targets", "targeting"], explanation: "The specific card or object an effect asks you to choose. Choose something that matches the restrictions printed on the effect.", example: "Defy targets a waiting spell, not the unit that spell would affect." },
  { term: "Conquer / hold", aliases: ["conquer", "conquest", "hold", "holding", "score", "point", "points"], explanation: "Conquer by gaining control after a battlefield contest settles. Hold by still controlling it when holding is checked in your Beginning phase. Each battlefield scores at most once per player per turn.", example: "At 7 points, holding can win; conquering has an extra final-point requirement taught later." },
] as const;

export function newPlayerTermsForText(text: string) {
  const words = new Set(text.toLowerCase().split(/[^a-z]+/));
  return NEW_PLAYER_TABLE_TERMS.filter(entry => entry.aliases.some(alias => words.has(alias))).slice(0, 5);
}
