export function nextUnreadBasicsTopic(currentId: string, readIds: readonly string[]): NewPlayerTopic | undefined {
  const current = NEW_PLAYER_BASICS.findIndex(topic => topic.id === currentId);
  const isUnread = (topic: NewPlayerTopic) => topic.id !== currentId && !readIds.includes(topic.id);
  return NEW_PLAYER_BASICS.slice(current + 1).find(isUnread) ?? NEW_PLAYER_BASICS.find(isUnread);
}

